import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 7
    text = raw_csv.lstrip("\ufeff")
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=",", quotechar='"', strict=False)

    parsed_rows = []
    try:
        parsed_rows.extend(reader)
    except csv.Error:
        pass

    if not parsed_rows:
        return {"columns": [""] * expected_width, "rows": []}

    header_terms = {
        "name", "date", "time", "type", "description", "total", "status",
        "id", "address", "code", "number", "category", "price", "title",
        "location", "count", "quantity", "contact", "email", "phone",
    }

    candidates = [
        (index, row)
        for index, row in enumerate(parsed_rows)
        if any(value.strip() for value in row)
    ]

    if not candidates:
        return {"columns": [""] * expected_width, "rows": []}

    def header_score(row):
        nonempty = [value.strip() for value in row if value.strip()]
        words = re.findall(r"[A-Za-z]+", " ".join(nonempty).lower())
        clues = sum(word in header_terms for word in words)
        alphabetic = sum(bool(re.search(r"[A-Za-z]", value)) for value in nonempty)
        width_match = int(len(row) == expected_width)
        return (width_match * 4 + len(nonempty) + clues * 3 + alphabetic, -len(row))

    header_index, header = max(candidates, key=lambda item: header_score(item[1]))
    width = max(expected_width, len(header), 1)

    columns = list(header[:width])
    columns.extend([""] * (width - len(columns)))

    rows = []
    for row in parsed_rows[header_index + 1:]:
        values = list(row)
        if len(values) > width:
            values = values[:width - 1] + [",".join(values[width - 1:])]
        values.extend([""] * (width - len(values)))
        rows.append(values)

    return {"columns": columns, "rows": rows}
